CREATE TABLE IF NOT EXISTS migrations (version TEXT PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, name TEXT NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'learner', settings TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS auth_sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reset_tokens (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits (key TEXT PRIMARY KEY, hits INTEGER NOT NULL, expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS content_sources (id TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS exam_versions (code TEXT PRIMARY KEY, revision TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS domains (id TEXT PRIMARY KEY, exam_code TEXT NOT NULL REFERENCES exam_versions(code), number INTEGER NOT NULL, name TEXT NOT NULL, weight INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS objectives (id TEXT PRIMARY KEY, domain_id TEXT NOT NULL REFERENCES domains(id), description TEXT NOT NULL, subtopics TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES content_sources(id));
CREATE TABLE IF NOT EXISTS questions (id TEXT PRIMARY KEY, current_revision INTEGER NOT NULL, status TEXT NOT NULL, fingerprint TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS question_revisions (question_id TEXT NOT NULL REFERENCES questions(id), revision INTEGER NOT NULL, content TEXT NOT NULL, created_by TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(question_id, revision));
CREATE TABLE IF NOT EXISTS question_options (question_id TEXT NOT NULL, revision INTEGER NOT NULL, option_id TEXT NOT NULL, text TEXT NOT NULL, explanation TEXT NOT NULL, is_correct INTEGER NOT NULL, PRIMARY KEY(question_id,revision,option_id), FOREIGN KEY(question_id,revision) REFERENCES question_revisions(question_id,revision));
CREATE TABLE IF NOT EXISTS question_objectives (question_id TEXT NOT NULL, revision INTEGER NOT NULL, objective_id TEXT NOT NULL REFERENCES objectives(id), PRIMARY KEY(question_id,revision,objective_id), FOREIGN KEY(question_id,revision) REFERENCES question_revisions(question_id,revision));
CREATE TABLE IF NOT EXISTS question_categories (question_id TEXT NOT NULL, revision INTEGER NOT NULL, category TEXT NOT NULL, PRIMARY KEY(question_id,revision,category), FOREIGN KEY(question_id,revision) REFERENCES question_revisions(question_id,revision));
CREATE TABLE IF NOT EXISTS content_reviews (id TEXT PRIMARY KEY, question_id TEXT NOT NULL, revision INTEGER NOT NULL, reviewer_id TEXT NOT NULL REFERENCES users(id), decision TEXT NOT NULL, note TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(question_id,revision) REFERENCES question_revisions(question_id,revision));
CREATE TABLE IF NOT EXISTS quiz_sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, mode TEXT NOT NULL, settings TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, completed_at TEXT, expires_at TEXT, cursor INTEGER NOT NULL DEFAULT 0, processed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS session_items (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES quiz_sessions(id) ON DELETE CASCADE, question_id TEXT NOT NULL, revision INTEGER NOT NULL, position INTEGER NOT NULL, selected TEXT, flagged INTEGER NOT NULL DEFAULT 0, answered_at TEXT, shown_at TEXT, retry INTEGER NOT NULL DEFAULT 0, feedback TEXT, FOREIGN KEY(question_id,revision) REFERENCES question_revisions(question_id,revision), UNIQUE(session_id,position));
CREATE TABLE IF NOT EXISTS attempts (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, session_id TEXT NOT NULL REFERENCES quiz_sessions(id) ON DELETE CASCADE, item_id TEXT NOT NULL UNIQUE REFERENCES session_items(id) ON DELETE CASCADE, question_id TEXT NOT NULL, revision INTEGER NOT NULL, selected TEXT NOT NULL, correct INTEGER NOT NULL, first_attempt INTEGER NOT NULL, retry INTEGER NOT NULL, retention INTEGER NOT NULL, confidence TEXT, duration_ms INTEGER NOT NULL, created_at TEXT NOT NULL, objective TEXT NOT NULL, difficulty TEXT NOT NULL, concept TEXT NOT NULL, FOREIGN KEY(question_id,revision) REFERENCES question_revisions(question_id,revision));
CREATE TABLE IF NOT EXISTS review_schedules (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, question_id TEXT NOT NULL REFERENCES questions(id), due_at TEXT NOT NULL, interval_days INTEGER NOT NULL, ease REAL NOT NULL, repetitions INTEGER NOT NULL, lapses INTEGER NOT NULL, retained INTEGER NOT NULL DEFAULT 0, last_at TEXT NOT NULL, state TEXT NOT NULL, PRIMARY KEY(user_id,question_id));
CREATE TABLE IF NOT EXISTS xp_events (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, event_key TEXT NOT NULL, amount INTEGER NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(user_id,event_key));
CREATE TABLE IF NOT EXISTS user_achievements (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, achievement_id TEXT NOT NULL, awarded_at TEXT NOT NULL, PRIMARY KEY(user_id,achievement_id));
CREATE TABLE IF NOT EXISTS flashcards (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, question_id TEXT REFERENCES questions(id), front TEXT NOT NULL, back TEXT NOT NULL, objective TEXT NOT NULL, due_at TEXT NOT NULL, interval_days INTEGER NOT NULL DEFAULT 0, repetitions INTEGER NOT NULL DEFAULT 0, UNIQUE(user_id,question_id));
CREATE TABLE IF NOT EXISTS flashcard_reviews (id TEXT PRIMARY KEY, card_id TEXT NOT NULL REFERENCES flashcards(id) ON DELETE CASCADE, rating INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS study_plans (user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, data TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS simulation_attempts (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, simulation_id TEXT NOT NULL, selected TEXT NOT NULL, score INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_log (id TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id) ON DELETE SET NULL, action TEXT NOT NULL, entity_id TEXT NOT NULL, detail TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS attempts_user_date ON attempts(user_id,created_at);
CREATE INDEX IF NOT EXISTS attempts_user_question ON attempts(user_id,question_id);
CREATE INDEX IF NOT EXISTS reviews_due ON review_schedules(user_id,due_at);
CREATE INDEX IF NOT EXISTS sessions_user_status ON quiz_sessions(user_id,status);
CREATE INDEX IF NOT EXISTS items_session ON session_items(session_id,position);
CREATE INDEX IF NOT EXISTS questions_status ON questions(status);
CREATE INDEX IF NOT EXISTS auth_expiration ON auth_sessions(expires_at);
